messages.content:
Siap! Game **Miko & Pohon Induk Terakhir** langsung dibangun ya. Asumsiku: kesulitan Normal dan target bergilir tiap 5 item benar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "miko-pohon-induk", title: "Miko & Pohon Induk Terakhir", seed: "miko-hutan-01",
  theme: { preset: "cartoon" },

  story: {
    title: "Miko & Pohon Induk Terakhir",
    hero: { name: "Miko", emoji: "🐱", desc: "Kucing ninja lincah penjaga hutan hujan tropis" },
    world: { name: "Hutan Hujan Tropis", emoji: "🌳" },
    mood: { from: "#14532d", to: "#0f766e" },
    prolog: [
      { text: "Miko, kucing ninja lincah, menjaga hutan hujan tropis yang dulu asri dan penuh kehidupan.", emoji: "🌳" },
      { text: "Pasukan robot penebang liar menebang hutan! Di tengah krisis, pohon induk terakhir ternyata bisa bicara dan memberi Miko kekuatan baru.", emoji: "🤖" },
      { text: "Bantu Miko berlari, ambil item sesuai kategori target, dan selamatkan pohon induk terakhir!", emoji: "🎯" }
    ],
    goal: { text: "Ambil 10 item yang cocok dengan kategori target untuk menyelamatkan pohon induk", correct: 10 },
    ending: {
      menang: { text: "Hutan kembali hijau dan pohon induk bersemi! Berkat kamu dan Miko, hutan hujan tropis hidup lagi.", emoji: "🏆" },
      kalah: { text: "Hutan masih suram, tapi Miko tak menyerah. Ayo coba lagi, kamu pasti bisa!", emoji: "💫" }
    }
  },

  learning: {
    subject: "Biologi",
    concept: "Rantai makanan: produsen, konsumen, dan pengurai",
    objectives: ["Mengelompokkan makhluk hidup sebagai produsen, konsumen, atau pengurai"],
    misconceptions: ["Jamur dianggap tumbuhan/produsen padahal ia pengurai"],
    mode: "category",
    categories: [
      { id: "produsen", label: "Produsen", color: "#3FA34D" },
      { id: "konsumen", label: "Konsumen", color: "#2F80ED" },
      { id: "pengurai", label: "Pengurai", color: "#E5484D" }
    ],
    items: [
      { id: "rumput", label: "Rumput", category: "produsen", explain: "Tumbuhan hijau berfotosintesis, membuat makanan sendiri." },
      { id: "pohon-pisang", label: "Pohon pisang", category: "produsen", explain: "Tumbuhan berdaun hijau yang berfotosintesis." },
      { id: "paku-air", label: "Paku air", category: "produsen", explain: "Tumbuhan hijau kecil yang berfotosintesis di air." },
      { id: "rusa", label: "Rusa", category: "konsumen", explain: "Hewan yang memakan tumbuhan, jadi konsumen." },
      { id: "ular", label: "Ular", category: "konsumen", explain: "Hewan pemakan hewan lain, termasuk konsumen." },
      { id: "elang", label: "Elang", category: "konsumen", explain: "Pemangsa yang makan hewan lain, jadi konsumen." },
      { id: "jamur", label: "Jamur", category: "pengurai", explain: "Menguraikan sisa makhluk hidup; bukan tumbuhan hijau." },
      { id: "bakteri", label: "Bakteri pengurai", category: "pengurai", explain: "Membusukkan sisa organisme menjadi zat hara." },
      { id: "cacing", label: "Cacing tanah", category: "pengurai", explain: "Menguraikan bahan organik di dalam tanah." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "robot", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "kayu", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game-mu siap dimainkan! 🎮 Selamat berlari bersama Miko menyelamatkan hutan!
